-- ============================================================
-- Schema database "fashion_bundle_optimizer"
-- Progetto: Ottimizzazione combinatoria (backtracking) per bundle
--           di outfit nel Fashion Retail - Chiara Pozzo (s312166)
-- Mercato gestito in questa versione: USA (dataset Adidas US)
-- ============================================================

CREATE DATABASE IF NOT EXISTS fashion_bundle_optimizer
    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE fashion_bundle_optimizer;

-- ------------------------------------------------------------
-- 0) Eliminazione tabelle in ordine sicuro (prima le "figlie" con
--    foreign key, poi le "genitrici"), cosi' lo script si puo'
--    rieseguire tutte le volte che vuoi senza errori
-- ------------------------------------------------------------
DROP TABLE IF EXISTS bundle_venduti;
DROP TABLE IF EXISTS prodotti_stock;
DROP TABLE IF EXISTS matrice_compatibilita_colori;
DROP TABLE IF EXISTS matrice_compatibilita_stili;
DROP TABLE IF EXISTS parametri_configurazione;

-- ------------------------------------------------------------
-- 1) Anagrafica Prodotti (Stock)
-- ------------------------------------------------------------
CREATE TABLE prodotti_stock (
    id_prodotto             VARCHAR(20)     PRIMARY KEY,   -- SKU reale Adidas
    nome                    VARCHAR(255)    NOT NULL,
    categoria_outfit        VARCHAR(30)     NOT NULL,       -- Capospalla / Maglieria / Pantaloni / Scarpe / Accessori / Vestiti
    segmento                VARCHAR(30),                    -- Women / Men / Kids / Originals / Training / ...
    stile                   VARCHAR(30)     NOT NULL,       -- Casual / Sportivo / Streetwear / Basic
    colore                  VARCHAR(30)     NOT NULL,
    prezzo_vendita          DECIMAL(8,2)    NOT NULL,
    prezzo_originale        DECIMAL(8,2),
    costo_acquisto          DECIMAL(8,2)    NOT NULL,       -- sintetico
    margine_unitario        DECIMAL(8,2)    NOT NULL,       -- sintetico
    margine_percentuale     DECIMAL(5,2)    NOT NULL,       -- sintetico
    quantita_stock          INT             NOT NULL,       -- sintetico
    data_ingresso_magazzino DATE            NOT NULL,       -- sintetico (per logica FIFO)
    giorni_in_magazzino     INT             NOT NULL,       -- sintetico (derivato dalla data)
    mercato                 VARCHAR(10)     NOT NULL DEFAULT 'USA',
    disponibilita           VARCHAR(20),
    url                     VARCHAR(500)
);

CREATE INDEX idx_categoria ON prodotti_stock (categoria_outfit);
CREATE INDEX idx_stile ON prodotti_stock (stile);
CREATE INDEX idx_colore ON prodotti_stock (colore);
CREATE INDEX idx_mercato ON prodotti_stock (mercato);

-- ------------------------------------------------------------
-- 2) Matrice di compatibilita' - COLORI
-- ------------------------------------------------------------
CREATE TABLE matrice_compatibilita_colori (
    colore_1                    VARCHAR(30) NOT NULL,
    colore_2                    VARCHAR(30) NOT NULL,
    punteggio_compatibilita     DECIMAL(3,2) NOT NULL,      -- 0.0 - 1.0
    PRIMARY KEY (colore_1, colore_2)
);

-- ------------------------------------------------------------
-- 3) Matrice di compatibilita' - STILI
-- ------------------------------------------------------------
CREATE TABLE matrice_compatibilita_stili (
    stile_1                     VARCHAR(30) NOT NULL,
    stile_2                     VARCHAR(30) NOT NULL,
    punteggio_compatibilita     DECIMAL(3,2) NOT NULL,
    PRIMARY KEY (stile_1, stile_2)
);

-- ------------------------------------------------------------
-- 4) Parametri di configurazione (preset strategie di Revenue Management)
-- ------------------------------------------------------------
CREATE TABLE parametri_configurazione (
    id_preset           INT PRIMARY KEY AUTO_INCREMENT,
    nome_preset         VARCHAR(50) NOT NULL,
    budget_max          DECIMAL(8,2) NOT NULL,
    margine_minimo_pct  DECIMAL(5,2) NOT NULL,
    peso_profitto_a     DECIMAL(3,2) NOT NULL,   -- peso 'a' nella funzione Z
    peso_anzianita_b    DECIMAL(3,2) NOT NULL    -- peso 'b' nella funzione Z
);

-- ------------------------------------------------------------
-- 5) Bundle generati e salvati (output dell'algoritmo, popolata a runtime)
-- ------------------------------------------------------------
CREATE TABLE bundle_venduti (
    id_bundle        INT PRIMARY KEY AUTO_INCREMENT,
    data_creazione   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    id_preset        INT,
    prezzo_totale    DECIMAL(8,2) NOT NULL,
    margine_totale   DECIMAL(8,2) NOT NULL,
    punteggio_z      DECIMAL(8,2) NOT NULL,
    prodotti_sku     VARCHAR(255) NOT NULL,   -- lista SKU separati da virgola
    FOREIGN KEY (id_preset) REFERENCES parametri_configurazione(id_preset)
);


-- ------------------------------------------------------------
-- DATI: prodotti_stock
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- DATI: matrice_compatibilita_colori
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- DATI: matrice_compatibilita_stili
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- DATI: parametri_configurazione (id_preset esplicito)
-- ------------------------------------------------------------
SET SQL_MODE='ALLOW_INVALID_DATES';
